class InvoiceCalculator {
  private tmpTotal?: number;
  calculate(items: number[]) {
    this.tmpTotal = items.reduce((s, v) => s + v, 0);
    const tax = this.computeTax(this.tmpTotal);
    const result = this.tmpTotal + tax;
    this.tmpTotal = undefined;
    return result;
  }
  private computeTax(total?: number) { return (total || 0) * 0.2; }
}

class ReportBuilder {
  private buffer = '';
  start() { this.buffer = ''; }
  addLine(line: string) { this.buffer += line + '\n'; }
  finish() { const out = this.buffer.trim(); this.buffer = ''; return out; }
}

